  sesNurturerSaysOnceMore: {  en: "Your nurturer says it once more…", es: "Tu nutridor lo dice una vez más…", ru: "Твой наставник говорит это ещё раз…", fr: "Ton accompagnant le redit une fois…", de: "Dein Begleiter sagt es noch einmal…", pt: "Seu nutridor diz mais uma vez…", it: "Il tuo nutritore lo ripete ancora una volta…", ja: "ナーチャラーがもう一度言ってくれるよ…", zh: "你的培育者再说一次……" , ht: "Moun k ap swen ou di l yon fwa ankò…", ko: "길잡이가 한 번 더 말해요…", tr: "Besleyicin bir kez daha söylüyor…", uk: "Ваш наставник каже це ще раз…", hi: "आपका नर्चरर इसे एक बार और कहता है…", ar: "راعيك يقولها مرّةً أخرى…", vi: "Người chăm của bạn nói lại một lần nữa…", id: "Pengasuhmu mengucapkannya sekali lagi…", pl: "Twój opiekun mówi to jeszcze raz…", th: "ผู้บ่มเพาะของคุณพูดมันอีกครั้ง…" },
  sesTapCardYouHear: {  en: "tap the card you hear", es: "toca la tarjeta que escuchas", ru: "нажми на карточку, которую слышишь", fr: "touche la carte que tu entends", de: "tippe auf die Karte, die du hörst", pt: "toque no cartão que você ouve", it: "tocca la carta che senti", ja: "聞こえたカードをタップ", zh: "点你听到的那张卡片" , ht: "manyen kat ou tande a", ko: "들리는 카드를 탭하세요", tr: "duyduğun karta dokun", uk: "торкніться картки, яку чуєте", hi: "जो कार्ड सुनें उस पर टैप करें", ar: "انقر البطاقة التي تسمعها", vi: "chạm thẻ bạn nghe", id: "ketuk kartu yang kamu dengar", pl: "dotknij karty, którą słyszysz", th: "แตะการ์ดที่คุณได้ยิน" },
  sesBigRoundEveryCard: {  en: "big round — every card!", es: "ronda grande: ¡todas las tarjetas!", ru: "большой раунд — все карточки!", fr: "grand tour — toutes les cartes !", de: "große Runde — alle Karten!", pt: "rodada grande — todos os cartões!", it: "giro grande — tutte le carte!", ja: "おおきなラウンド——ぜんぶのカード！", zh: "大轮——所有卡片！" , ht: "gwo tou — chak kat!", ko: "큰 판 — 모든 카드!", tr: "büyük tur — her kart!", uk: "великий раунд — усі картки!", hi: "बड़ा राउंड — हर कार्ड!", ar: "جولة كبيرة — كلّ بطاقة!", vi: "vòng lớn — tất cả các thẻ!", id: "ronde besar — semua kartu!", pl: "wielka runda — każda karta!", th: "รอบใหญ่ — ทุกการ์ด!" },
  sesNewCardJustListen: {  en: "New card! Just listen — echo it if it feels good.", es: "¡Tarjeta nueva! Solo escucha; repítela si te apetece.", ru: "Новая карточка! Просто слушай — повтори, если захочется.", fr: "Nouvelle carte ! Écoute simplement — répète-la si ça te dit.", de: "Neue Karte! Hör einfach zu — sprich sie nach, wenn es sich gut anfühlt.", pt: "Cartão novo! Só escute — repita se sentir vontade.", it: "Carta nuova! Ascolta e basta — ripetila se ti va.", ja: "新しいカード！ただ聞くだけ——気が向いたら、まねしてみて。", zh: "新卡片！只管听——想跟读就跟读。" , ht: "Nouvo kat! Koute sèlman — repete l si ou santi l byen.", ko: "새 카드예요! 그냥 들어요 — 따라 하고 싶으면 따라 해도 좋아요.", tr: "Yeni kart! Sadece dinle — istersen tekrarla.", uk: "Нова картка! Просто слухайте — повторіть, якщо хочеться.", hi: "नया कार्ड! बस सुनें — अच्छा लगे तो दोहराएँ।", ar: "بطاقة جديدة! استمع فقط — كرّرها إن شعرت بذلك.", vi: "Thẻ mới! Chỉ nghe thôi — nhại lại nếu thấy thích.", id: "Kartu baru! Cukup dengar — tirukan kalau terasa nyaman.", pl: "Nowa karta! Po prostu słuchaj — powtórz, jeśli masz ochotę.", th: "การ์ดใหม่! แค่ฟัง — พูดตามถ้ารู้สึกอยากพูด" },
  sesNoPressureSpeak: {  en: "No pressure to speak.", es: "Sin presión por hablar.", ru: "Говорить не обязательно.", fr: "Aucune pression pour parler.", de: "Kein Druck zu sprechen.", pt: "Sem pressão para falar.", it: "Nessuna pressione a parlare.", ja: "話すプレッシャーはなし。", zh: "不必急着开口。" , ht: "Pa gen presyon pou pale.", ko: "말해야 한다는 부담은 없어요.", tr: "Konuşma baskısı yok.", uk: "Без тиску говорити.", hi: "बोलने का कोई दबाव नहीं।", ar: "لا ضغط للكلام.", vi: "Không áp lực phải nói.", id: "Tak ada tekanan untuk bicara.", pl: "Żadnej presji mówienia.", th: "ไม่มีแรงกดดันให้พูด" },
