  sesSwitchRoles: {  en: "Switch roles", es: "Cambiar roles", ru: "Поменяться ролями", fr: "Échanger les rôles", de: "Rollen tauschen", pt: "Trocar de papéis", it: "Scambia i ruoli", ja: "役割を交代", zh: "切换角色" , ht: "Chanje wòl", ko: "역할 바꾸기", tr: "Rolleri değiştir", uk: "Поміняти ролі", hi: "भूमिकाएँ बदलें", ar: "بدّل الأدوار", vi: "Đổi vai", id: "Tukar peran", pl: "Zamień role", th: "สลับบทบาท" },
